+:root {
+  color-scheme: light;
+  --bg: #f6f3ee;
+  --card: #ffffff;
+  --text: #1e293b;
+  --muted: #64748b;
+  --accent: #f97316;
+  --accent-soft: #fff7ed;
+  --border: #eadfd3;
+  --shadow: 0 24px 70px rgba(30, 41, 59, 0.14);
+  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+body {
+  min-height: 100vh;
+  margin: 0;
+  color: var(--text);
+  background:
+    radial-gradient(circle at top left, rgba(249, 115, 22, 0.18), transparent 34rem),
+    linear-gradient(135deg, #fffaf3 0%, var(--bg) 48%, #eef4ff 100%);
+}
+
+.page-shell {
+  width: min(920px, calc(100% - 32px));
+  margin: 0 auto;
+  padding: 72px 0;
+}
+
+.hero {
+  max-width: 720px;
+  margin-bottom: 32px;
+}
+
+.eyebrow {
+  width: fit-content;
+  margin: 0 0 14px;
+  padding: 8px 12px;
+  color: #9a3412;
+  background: var(--accent-soft);
+  border: 1px solid #fed7aa;
+  border-radius: 999px;
+  font-size: 0.78rem;
+  font-weight: 800;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+}
+
+h1 {
+  margin: 0;
+  color: #111827;
+  font-size: clamp(2.4rem, 7vw, 4.8rem);
+  line-height: 0.95;
+  letter-spacing: -0.07em;
+}
+
+.hero-copy {
+  max-width: 620px;
+  margin: 22px 0 0;
+  color: var(--muted);
+  font-size: clamp(1.05rem, 2vw, 1.2rem);
+  line-height: 1.7;
+}
+
+.faq-card {
+  display: grid;
+  gap: 14px;
+  padding: 18px;
+  background: rgba(255, 255, 255, 0.78);
+  border: 1px solid rgba(234, 223, 211, 0.8);
+  border-radius: 28px;
+  box-shadow: var(--shadow);
+  backdrop-filter: blur(18px);
+}
+
+.example {
+  overflow: hidden;
+  background: var(--card);
+  border: 1px solid var(--border);
+  border-radius: 20px;
+  transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
+}
+
+.example:has(.question[aria-expanded="true"]) {
+  border-color: rgba(249, 115, 22, 0.42);
+  box-shadow: 0 18px 38px rgba(249, 115, 22, 0.12);
+}
+
+.question {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 20px;
+  width: 100%;
+  padding: 24px;
+  color: inherit;
+  background: transparent;
+  border: 0;
+  font: inherit;
+  font-size: 1.05rem;
+  font-weight: 800;
+  text-align: left;
+  cursor: pointer;
+}
+
+.question:focus-visible {
+  outline: 3px solid rgba(249, 115, 22, 0.45);
+  outline-offset: -6px;
+  border-radius: 20px;
+}
+
+.icon {
+  position: relative;
+  flex: 0 0 auto;
+  width: 32px;
+  height: 32px;
+  background: var(--accent-soft);
+  border-radius: 50%;
+}
+
+.icon::before,
+.icon::after {
+  position: absolute;
+  top: 50%;
+  left: 50%;
+  width: 14px;
+  height: 2px;
+  background: var(--accent);
+  border-radius: 999px;
+  content: "";
+  transform: translate(-50%, -50%);
+  transition: transform 180ms ease;
+}
+
+.icon::after {
+  transform: translate(-50%, -50%) rotate(90deg);
+}
+
+.question[aria-expanded="true"] .icon::after {
+  transform: translate(-50%, -50%) rotate(0deg);
+}
+
+.details {
+  padding: 0 24px 24px;
+  color: var(--muted);
+  font-size: 1rem;
+  line-height: 1.7;
+}
+
+.details p {
+  margin: 0;
+}
+
+@media (max-width: 640px) {
+  .page-shell {
+    width: min(100% - 24px, 920px);
+    padding: 42px 0;
+  }
+
+  .faq-card {
+    padding: 10px;
+    border-radius: 22px;
+  }
+
+  .question {
+    padding: 20px;
+  }
+
+  .details {
+    padding: 0 20px 20px;
+  }
+}
*** Add File: script.js
+const questions = document.querySelectorAll(".question");
+
+questions.forEach((question) => {
+  question.addEventListener("click", () => {
+    const details = document.getElementById(question.getAttribute("aria-controls"));
+    const isExpanded = question.getAttribute("aria-expanded") === "true";
+
+    question.setAttribute("aria-expanded", String(!isExpanded));
+    details.hidden = isExpanded;
+  });
+});
*** End Patch
